package general

import (
	"path"
	"strconv"
	"testing"

	kzgPrysm "github.com/OffchainLabs/prysm/v6/beacon-chain/blockchain/kzg"
	"github.com/OffchainLabs/prysm/v6/testing/require"
	"github.com/OffchainLabs/prysm/v6/testing/spectest/utils"
	"github.com/OffchainLabs/prysm/v6/testing/util"
	"github.com/ethereum/go-ethereum/common/hexutil"
	"github.com/ghodss/yaml"
)

func TestRecoverCellsAndKzgProofs(t *testing.T) {
	type input struct {
		CellIndices []string `json:"cell_indices"`
		Cells       []string `json:"cells"`
	}

	type data struct {
		Input  input      `json:"input"`
		Output [][]string `json:"output"`
	}
	require.NoError(t, kzgPrysm.Start())
	testFolders, testFolderPath := utils.TestFolders(t, "general", "fulu", "kzg/recover_cells_and_kzg_proofs/kzg-mainnet")
	if len(testFolders) == 0 {
		t.Fatalf("No test folders found for %s/%s/%s", "general", "fulu", "kzg/recover_cells_and_kzg_proofs/kzg-mainnet")
	}
	for _, folder := range testFolders {
		t.Run(folder.Name(), func(t *testing.T) {
			file, err := util.BazelFileBytes(path.Join(testFolderPath, folder.Name(), "data.yaml"))
			require.NoError(t, err)
			test := &data{}
			require.NoError(t, yaml.Unmarshal(file, test))
			cellIndicesRaw := test.Input.CellIndices
			cellIndices := make([]uint64, 0, len(cellIndicesRaw))
			for _, idx := range cellIndicesRaw {
				i, err := strconv.ParseUint(idx, 10, 64)
				require.NoError(t, err)
				cellIndices = append(cellIndices, i)
			}

			// Check if cell indices are sorted
			isSorted := true
			for i := 1; i < len(cellIndices); i++ {
				if cellIndices[i] <= cellIndices[i-1] {
					isSorted = false
					break
				}
			}

			// If cell indices are not sorted and test expects failure, return early
			if !isSorted && test.Output == nil {
				require.IsNil(t, test.Output)
				return
			}
			cellsRaw := test.Input.Cells
			cells := make([]kzgPrysm.Cell, 0, len(cellsRaw))
			for _, cellRaw := range cellsRaw {
				cell, err := hexutil.Decode(cellRaw)
				require.NoError(t, err)
				if len(cell) != kzgPrysm.BytesPerCell {
					require.IsNil(t, test.Output)
					return
				}
				cells = append(cells, kzgPrysm.Cell(cell))
			}

			// Recover the cells and proofs for the corresponding blob
			cellsAndProofsForBlob, err := kzgPrysm.RecoverCellsAndKZGProofs(cellIndices, cells)
			if test.Output != nil {
				require.NoError(t, err)
				var combined [][]string
				cs := cellsAndProofsForBlob.Cells
				csRaw := make([]string, 0, len(cs))
				for _, c := range cs {
					csRaw = append(csRaw, hexutil.Encode(c[:]))
				}
				ps := cellsAndProofsForBlob.Proofs
				psRaw := make([]string, 0, len(ps))
				for _, p := range ps {
					psRaw = append(psRaw, hexutil.Encode(p[:]))
				}
				combined = append(combined, csRaw)
				combined = append(combined, psRaw)
				require.DeepEqual(t, test.Output, combined)
			} else {
				require.NotNil(t, err)
			}
		})
	}
}

package kzg

import (
	_ "embed"
	"encoding/json"

	GoKZG "github.com/crate-crypto/go-kzg-4844"
	CKZG "github.com/ethereum/c-kzg-4844/v2/bindings/go"
	"github.com/ethereum/go-ethereum/common/hexutil"
	"github.com/pkg/errors"
)

var (
	// https://github.com/ethereum/consensus-specs/blob/master/presets/mainnet/trusted_setups/trusted_setup_4096.json
	//go:embed trusted_setup_4096.json
	embeddedTrustedSetup []byte // 1.2Mb
	kzgContext           *GoKZG.Context
	kzgLoaded            bool
)

type TrustedSetup struct {
	G1Monomial [GoKZG.ScalarsPerBlob]GoKZG.G1CompressedHexStr `json:"g1_monomial"`
	G1Lagrange [GoKZG.ScalarsPerBlob]GoKZG.G1CompressedHexStr `json:"g1_lagrange"`
	G2Monomial [65]GoKZG.G2CompressedHexStr                   `json:"g2_monomial"`
}

func Start() error {
	trustedSetup := &TrustedSetup{}
	err := json.Unmarshal(embeddedTrustedSetup, trustedSetup)
	if err != nil {
		return errors.Wrap(err, "could not parse trusted setup JSON")
	}

	kzgContext, err = GoKZG.NewContext4096(&GoKZG.JSONTrustedSetup{
		SetupG2:         trustedSetup.G2Monomial[:],
		SetupG1Lagrange: trustedSetup.G1Lagrange,
	})
	if err != nil {
		return errors.Wrap(err, "could not initialize go-kzg context")
	}

	// Length of a G1 point, converted from hex to binary.
	g1MonomialBytes := make([]byte, len(trustedSetup.G1Monomial)*(len(trustedSetup.G1Monomial[0])-2)/2)
	for i, g1 := range &trustedSetup.G1Monomial {
		copy(g1MonomialBytes[i*(len(g1)-2)/2:], hexutil.MustDecode(g1))
	}

	// Length of a G1 point, converted from hex to binary.
	g1LagrangeBytes := make([]byte, len(trustedSetup.G1Lagrange)*(len(trustedSetup.G1Lagrange[0])-2)/2)
	for i, g1 := range &trustedSetup.G1Lagrange {
		copy(g1LagrangeBytes[i*(len(g1)-2)/2:], hexutil.MustDecode(g1))
	}

	// Length of a G2 point, converted from hex to binary.
	g2MonomialBytes := make([]byte, len(trustedSetup.G2Monomial)*(len(trustedSetup.G2Monomial[0])-2)/2)
	for i, g2 := range &trustedSetup.G2Monomial {
		copy(g2MonomialBytes[i*(len(g2)-2)/2:], hexutil.MustDecode(g2))
	}

	if !kzgLoaded {
		const precompute uint = 8

		kzgLoaded = true

		// Free the current trusted setup before running this method.
		// CKZG panics if the same setup is run multiple times.
		if err = CKZG.LoadTrustedSetup(g1MonomialBytes, g1LagrangeBytes, g2MonomialBytes, precompute); err != nil {
			return errors.Wrap(err, "load trust setup")
		}
	}

	return nil
}

